    final recovery = config.imageRecovery!;
    if (passes >= 2) {
      exhausted = true;
      await emit(
        ImagePayloadRecoveryEvent(
          pass: 2,
          dropped: recovery.lastDropped,
          stripped: recovery.lastStripped,
          failed: true,
          providerError: finished.errorMessage,
        ),
